fn selected_local_resource_config(&self) -> Option<NativeModelConfig> {
    match self.model_backend {
        ModelBackendPreference::ManagedLocal => self.managed_local.selected_config().ok(),
        ModelBackendPreference::OllamaCompatible
            if !self.local_model_name.trim().is_empty() =>
        {
            Some(NativeModelConfig::Local(LocalModelConfig {
                endpoint: self.local_model_endpoint.clone(),
                model: self.local_model_name.clone(),
            }))
        }
        ModelBackendPreference::OllamaCompatible
        | ModelBackendPreference::HostedApi
        | ModelBackendPreference::Enterprise => None,
    }
}
